5	import br.com.loja.checkout.clube.NivelClube;
6	import br.com.loja.checkout.cupom.Cupom;
7	import br.com.loja.checkout.dominio.Carrinho;
8	import br.com.loja.checkout.dominio.Catalogo;
9	import br.com.loja.checkout.dominio.CheckoutException;
10	import br.com.loja.checkout.dominio.Item;
11	import br.com.loja.checkout.dominio.Regiao;
12	import br.com.loja.checkout.dominio.Resumo;
13	import br.com.loja.checkout.entrega.ModalidadeEntrega;
14	import br.com.loja.checkout.pagamento.FormaPagamento;
15	import br.com.loja.checkout.pagamento.Pagamento;
16	import java.math.BigDecimal;
17	import java.util.List;
18	import java.util.Optional;
19	import org.springframework.stereotype.Service;
20	
21	@Service
22	public class CheckoutService {
23	
24	    private final Catalogo<NivelClube> niveis;
25	    private final Catalogo<ModalidadeEntrega> modalidades;
26	    private final Catalogo<Cupom> cupons;
27	    private final Catalogo<FormaPagamento> formas;
28	
29	    public CheckoutService(List<NivelClube> niveis, List<ModalidadeEntrega> modalidades, List<Cupom> cupons,
30	            List<FormaPagamento> formas) {
31	        this.niveis = new Catalogo<>(niveis);
32	        this.modalidades = new Catalogo<>(modalidades);
33	        this.cupons = new Catalogo<>(cupons);
34	        this.formas = new Catalogo<>(formas);
35	    }
36	
37	    public Resumo calcular(ResumoRequest pedido) {
38	        Carrinho carrinho = carrinho(pedido.itens());
39	        NivelClube nivel = niveis.buscar(pedido.nivelClube()).orElseThrow(() -> erro("NIVEL_CLUBE_INVALIDO"));
40	        Regiao regiao = Regiao.buscar(pedido.regiao()).orElseThrow(() -> erro("REGIAO_INVALIDA"));
41	
42	        ModalidadeEntrega modalidade = modalidades.buscar(pedido.modalidadeEntrega())
43	                .orElseThrow(() -> erro("MODALIDADE_INVALIDA"));
44	        exigir(modalidade.atende(carrinho), "MODALIDADE_INDISPONIVEL");
45	
46	        Cupom cupom = cupom(pedido.cupom());
47	        exigir(cupom.aplicavel(carrinho), "CUPOM_NAO_APLICAVEL");
48	
49	        BigDecimal subtotal = carrinho.subtotal();
50	        BigDecimal frete = nivel.frete(modalidade.frete(carrinho));
51	        BigDecimal desconto = cupom.desconto(carrinho, frete);
52	        BigDecimal seguro = regiao.seguro(carrinho);
53	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
54	
55	        FormaPagamento forma = formas.buscar(pedido.formaPagamento())
56	                .orElseThrow(() -> erro("FORMA_PAGAMENTO_INVALIDA"));
57	        int parcelas = Optional.ofNullable(pedido.parcelas()).orElse(1);
58	        exigir(forma.parcelasPermitidas(parcelas), "PARCELAMENTO_INVALIDO");
59	        exigir(forma.atende(totalPedido), "FORMA_PAGAMENTO_INDISPONIVEL");
60	        Pagamento pagamento = forma.calcular(totalPedido, parcelas);
61	
62	        return new Resumo(
63	                subtotal,
64	                desconto,
65	                frete,
66	                modalidade.prazoDias(),
67	                seguro,
68	                pagamento.totalFinal().subtract(totalPedido),
69	                pagamento.totalFinal(),
70	                parcelas,
71	                pagamento.valorParcela(),
72	                nivel.credito(carrinho),
73	                nivel.brinde(carrinho));
74	    }
75	
76	    private Carrinho carrinho(List<ItemRequest> itens) {
77	        exigir(itens != null && !itens.isEmpty() && itens.stream().allMatch(CheckoutService::itemValido),
78	                "PEDIDO_INVALIDO");
79	        return new Carrinho(itens.stream()
80	                .map(i -> new Item(i.nome(), i.precoUnitario(), i.quantidade(), i.pesoKg()))
81	                .toList());
82	    }
83	
84	    private static boolean itemValido(ItemRequest item) {
85	        return item != null
86	                && positivo(item.precoUnitario())
87	                && item.quantidade() != null && item.quantidade() > 0
88	                && positivo(item.pesoKg());
89	    }
90	
91	    private static boolean positivo(BigDecimal valor) {
92	        return valor != null && valor.signum() > 0;
93	    }
94	
95	    private Cupom cupom(String codigo) {
96	        if (codigo == null) {
97	            return Cupom.NENHUM;
98	        }
99	        return cupons.buscar(codigo).orElseThrow(() -> erro("CUPOM_INVALIDO"));
100	    }
101	
102	    private static void exigir(boolean condicao, String codigoErro) {
103	        if (!condicao) {
104	            throw erro(codigoErro);
105	        }
106	    }
107	
108	    private static CheckoutException erro(String codigo) {
109	        return new CheckoutException(codigo);
110	    }
111	}
