4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	import java.math.RoundingMode;
7	import org.springframework.stereotype.Component;
8	
9	@Component
10	class Cartao implements FormaPagamento {
11	
12	    private static final int MAXIMO_PARCELAS = 12;
13	    private static final int MAXIMO_SEM_JUROS = 3;
14	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
15	
16	    public String codigo() {
17	        return "CARTAO";
18	    }
19	
20	    public boolean parcelasPermitidas(int parcelas) {
21	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
22	    }
23	
24	    public boolean atende(BigDecimal totalPedido) {
25	        return true;
26	    }
27	
28	    public Pagamento calcular(BigDecimal totalPedido, int parcelas) {
29	        if (parcelas <= MAXIMO_SEM_JUROS) {
30	            BigDecimal parcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
31	            return new Pagamento(totalPedido, parcela);
32	        }
33	        BigDecimal parcela = Dinheiro.centavos(parcelaPrice(totalPedido, parcelas));
34	        return new Pagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela);
35	    }
36	
37	    /** Tabela Price: total × taxa ÷ (1 − (1 + taxa)^−n). */
38	    private static BigDecimal parcelaPrice(BigDecimal total, int parcelas) {
39	        MathContext mc = MathContext.DECIMAL128;
40	        BigDecimal fatorNegativo = BigDecimal.ONE.divide(BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, mc), mc);
41	        return total.multiply(TAXA_MENSAL, mc).divide(BigDecimal.ONE.subtract(fatorNegativo, mc), mc);
42	    }
43	}
